class CalendarHomeScreen extends StatefulWidget {
  const CalendarHomeScreen({super.key});

  @override
  State<CalendarHomeScreen> createState() => _CalendarHomeScreenState();
}

class _CalendarHomeScreenState extends State<CalendarHomeScreen> {
  int selectedLiveryIndex = 0;
  final Map<int, int> bestPositionByRound = {};
  final Map<int, int> pointsByRound = {};

  int get totalPoints => pointsByRound.values.fold(0, (a, b) => a + b);

  @override
  void initState() {
    super.initState();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.portraitUp,
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
  }

  Future<void> _startRace(CircuitInfo circuit) async {
    final RaceFinishData? result = await Navigator.push<RaceFinishData>(
      context,
      MaterialPageRoute(
        builder: (_) => CockpitRaceScreen(
          circuit: circuit,
          livery: kLiveries[selectedLiveryIndex],
        ),
      ),
    );

    if (result != null && mounted) {
      setState(() {
        final int prevBest = bestPositionByRound[circuit.round] ?? 99;
        if (result.position < prevBest) {
          bestPositionByRound[circuit.round] = result.position;
        }
        final int prevPts = pointsByRound[circuit.round] ?? 0;
        if (result.points > prevPts) {
          pointsByRound[circuit.round] = result.points;
        }
      });

      if (result.nextRound && circuit.round < 24) {
        _startRace(kAll24Circuits[circuit.round]);
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final TeamLivery livery = kLiveries[selectedLiveryIndex];

    return Scaffold(
      body: SafeArea(
        child: Column(
          children: [
            // Header Championship Banner
            Container(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: [livery.primary, const Color(0xFF141824)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
                border: const Border(bottom: BorderSide(color: Color(0xFF263047))),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      const Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'F1 WORLD CHAMPIONSHIP',
                            style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900, letterSpacing: 1.4),
                          ),
                          Text(
                            'Temporada Completa • 24 Grandes Premios • Vista Cockpit 3D',
                            style: TextStyle(fontSize: 11, color: Colors.white70),
                          ),
                        ],
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                        decoration: BoxDecoration(
                          color: const Color(0xCC090C14),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(color: const Color(0xFFFFD54F)),
                        ),
                        child: Column(
                          children: [
                            Text(
                              '$totalPoints PTS',
                              style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w900, color: Color(0xFFFFD54F)),
                            ),
                            Text(
                              '${bestPositionByRound.length}/24 GPs',
                              style: const TextStyle(fontSize: 10, color: Colors.white70),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  // Team Livery Selector
                  SizedBox(
                    height: 36,
                    child: ListView.separated(
                      scrollDirection: Axis.horizontal,
                      itemCount: kLiveries.length,
                      separatorBuilder: (_, __) => const SizedBox(width: 8),
                      itemBuilder: (ctx, i) {
                        final TeamLivery item = kLiveries[i];
                        final bool selected = i == selectedLiveryIndex;
                        return GestureDetector(
                          onTap: () => setState(() => selectedLiveryIndex = i),
                          child: Container(
                            padding: const EdgeInsets.symmetric(horizontal: 12),
                            alignment: Alignment.center,
                            decoration: BoxDecoration(
                              color: selected ? item.primary : const Color(0xAA0B101C),
                              borderRadius: BorderRadius.circular(18),
                              border: Border.all(
                                color: selected ? Colors.white : item.primary,
                                width: selected ? 2 : 1,
                              ),
                            ),
                            child: Row(
                              children: [
                                Container(
                                  width: 10,
                                  height: 10,
                                  decoration: BoxDecoration(
                                    color: item.secondary,
                                    shape: BoxShape.circle,
                                  ),
                                ),
                                const SizedBox(width: 6),
                                Text(
                                  item.name,
                                  style: const TextStyle(fontSize: 12, fontWeight: FontWeight.bold),
                                ),
                              ],
                            ),
                          ),
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),

            // 24 Races List
            Expanded(
              child: ListView.builder(
                padding: const EdgeInsets.all(12),
                itemCount: kAll24Circuits.length,
                itemBuilder: (ctx, idx) {
                  final CircuitInfo c = kAll24Circuits[idx];
                  final int? bestPos = bestPositionByRound[c.round];
                  return Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: InkWell(
                      onTap: () => _startRace(c),
                      borderRadius: BorderRadius.circular(12),
                      child: Container(
                        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 11),
                        decoration: BoxDecoration(
                          color: const Color(0xFF131926),
                          borderRadius: BorderRadius.circular(12),
                          border: Border.all(
                            color: bestPos == 1 ? const Color(0xFFFFD54F) : const Color(0xFF232E47),
                          ),
                        ),
                        child: Row(
                          children: [
                            Container(
                              width: 44,
                              height: 44,
                              alignment: Alignment.center,
                              decoration: BoxDecoration(
                                gradient: LinearGradient(
                                  colors: [c.skyTop, c.skyBottom],
                                  begin: Alignment.topCenter,
                                  end: Alignment.bottomCenter,
                                ),
                                borderRadius: BorderRadius.circular(10),
                                border: Border.all(color: c.kerbA, width: 1.5),
                              ),
                              child: Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                children: [
                                  Text(
                                    'R${c.round.toString().padLeft(2, '0')}',
                                    style: const TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: Colors.white70),
                                  ),
                                  Text(
                                    c.code,
                                    style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w900, color: Colors.white),
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(width: 12),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    c.gpName,
                                    style: const TextStyle(fontSize: 15, fontWeight: FontWeight.bold),
                                  ),
                                  const SizedBox(height: 2),
                                  Text(
                                    '${c.circuitName} • ${c.timeLabel}',
                                    style: const TextStyle(fontSize: 11, color: Colors.white60),
                                  ),
                                ],
                              ),
                            ),
                            if (bestPos != null)
                              Container(
                                margin: const EdgeInsets.only(right: 8),
                                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                                decoration: BoxDecoration(
                                  color: bestPos <= 3 ? const Color(0x33FFD54F) : const Color(0xFF1E283D),
                                  borderRadius: BorderRadius.circular(8),
                                ),
                                child: Text(
                                  'P$bestPos',
                                  style: TextStyle(
                                    fontSize: 12,
                                    fontWeight: FontWeight.w900,
                                    color: bestPos == 1 ? const Color(0xFFFFD54F) : Colors.white,
                                  ),
                                ),
                              ),
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
                              decoration: BoxDecoration(
                                color: livery.primary,
                                borderRadius: BorderRadius.circular(8),
                              ),
                              child: const Text(
                                'CORRER',
                                style: TextStyle(fontSize: 11, fontWeight: FontWeight.w900, letterSpacing: 0.8),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class RaceFinishData {
  final int position;
  final int points;
  final bool nextRound;

  RaceFinishData({
    required this.position,
    required this.points,
    this.nextRound = false,
  });
}

class AiDriver {
  final String code;
  final Color bodyColor;
  final Color wingColor;
  double laneX;
  double targetLaneX;
  double trackDist;
  double baseSpeedKmh;

  AiDriver({
    required this.code,
    required this.bodyColor,
    required this.wingColor,
    required this.laneX,
    required this.trackDist,
    required this.baseSpeedKmh,
  }) : targetLaneX = laneX;
}

class CockpitRaceScreen extends StatefulWidget {
  final CircuitInfo circuit;
  final TeamLivery livery;

  const CockpitRaceScreen({
    super.key,
    required this.circuit,
    required this.livery,
  });

  @override
  State<CockpitRaceScreen> createState() => _CockpitRaceScreenState();
}

class _CockpitRaceScreenState extends State<CockpitRaceScreen> {
  static const int totalLaps = 5;
  static const int totalCars = 22;

  final Random rng = Random();
  Timer? _timer;

  bool cockpitCamera = true;
  bool raceFinished = false;
  double startLightsTimer = 3.2; // 3..2..1..GO!

  double speedKmh = 0.0;
  double carX = 0.0;
  double steerAngle = 0.0;
  double playerDist = 0.0;
  double lapStartTime = 0.0;
  double totalRaceTime = 0.0;
  double bestLapTime = 999.0;
  double fastLapTime = 999.0;
  double ersCharge = 100.0;
  double hitFlash = 0.0;
  double wheelSpin = 0.0;

  bool leftHeld = false;
  bool rightHeld = false;
  bool gasHeld = false;
  bool brakeHeld = false;
  bool ersHeld = false;

  late List<AiDriver> aiDrivers;

  @override
  void initState() {
    super.initState();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    _initGrid();
    _timer = Timer.periodic(const Duration(milliseconds: 16), (_) => _update(0.016));
  }

  void _initGrid() {
    const List<Map<String, Object>> gridTemplates = [
      {'c': 'VER', 'b': Color(0xFF14245C), 'w': Color(0xFFE10600)},
      {'c': 'NOR', 'b': Color(0xFFFF7A00), 'w': Color(0xFF111111)},
      {'c': 'LEC', 'b': Color(0xFFD9121B), 'w': Color(0xFFFFD100)},
      {'c': 'PIA', 'b': Color(0xFFFF7A00), 'w': Color(0xFF111111)},
      {'c': 'HAM', 'b': Color(0xFFD9121B), 'w': Color(0xFFFFFFFF)},
      {'c': 'RUS', 'b': Color(0xFF1F2429), 'w': Color(0xFF00D2BE)},
      {'c': 'ANT', 'b': Color(0xFF1F2429), 'w': Color(0xFF00D2BE)},
      {'c': 'ALO', 'b': Color(0xFF00594F), 'w': Color(0xFFCEDC00)},
      {'c': 'STR', 'b': Color(0xFF00594F), 'w': Color(0xFFCEDC00)},
      {'c': 'SAI', 'b': Color(0xFF005AFF), 'w': Color(0xFFFFFFFF)},
      {'c': 'ALB', 'b': Color(0xFF005AFF), 'w': Color(0xFFFFFFFF)},
      {'c': 'GAS', 'b': Color(0xFF0090FF), 'w': Color(0xFFFF69B4)},
      {'c': 'DOO', 'b': Color(0xFF0090FF), 'w': Color(0xFFFF69B4)},
      {'c': 'TSU', 'b': Color(0xFF1836B2), 'w': Color(0xFFFFFFFF)},
      {'c': 'LAW', 'b': Color(0xFF1836B2), 'w': Color(0xFFFFFFFF)},
      {'c': 'HUL', 'b': Color(0xFF1A1E24), 'w': Color(0xFF00E676)},
      {'c': 'BOR', 'b': Color(0xFF1A1E24), 'w': Color(0xFF00E676)},
      {'c': 'OCO', 'b': Color(0xFFE0E0E0), 'w': Color(0xFFE10600)},
      {'c': 'BEA', 'b': Color(0xFFE0E0E0), 'w': Color(0xFFE10600)},
      {'c': 'RIC', 'b': Color(0xFF1B2B4B), 'w': Color(0xFFFFC107)},
      {'c': 'BOT', 'b': Color(0xFF212121), 'w': Color(0xFF00B0FF)},
    ];

    aiDrivers = [];
    // Player starts P21/22 (just like the screenshot!) so there is immediate action ahead & 1 car behind
    playerDist = 18.0;
    for (int i = 0; i < gridTemplates.length; i++) {
      final int gridSlot = i < 20 ? (20 - i) : 0; // 20 cars ahead, 1 behind
      final double startDist = gridSlot == 0 ? 4.0 : (playerDist + 16.0 + (gridSlot * 16.0));
      final double lane = (i % 2 == 0) ? -0.45 : 0.45;
      // Competitive speed band so player can fight through the field over 5 laps
      final double pace = 228.0 + ((20 - i) * 2.15);
      aiDrivers.add(
        AiDriver(
          code: gridTemplates[i]['c'] as String,
          bodyColor: gridTemplates[i]['b'] as Color,
          wingColor: gridTemplates[i]['w'] as Color,
          laneX: lane,
          trackDist: startDist,
          baseSpeedKmh: pace,
        ),
      );
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.portraitUp,
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    super.dispose();
  }

  int get currentLap {
    final int lap = (playerDist / widget.circuit.lapLengthMeters).floor() + 1;
    return lap.clamp(1, totalLaps).toInt();
  }

  int get currentPosition {
    int ahead = 0;
    for (final ai in aiDrivers) {
      if (ai.trackDist > playerDist) ahead++;
    }
    return (ahead + 1).clamp(1, totalCars).toInt();
  }

  double _trackCurveAt(double dist) {
    final CircuitInfo c = widget.circuit;
    return (sin(dist * c.curveFreq) * 0.65 + cos(dist * c.curveFreq * 0.43 + c.mapSeed) * 0.35) * c.curveAmp;
  }

  void _update(double dt) {
    if (raceFinished) return;

    if (startLightsTimer > 0) {
      startLightsTimer = max(0.0, startLightsTimer - dt);
      if (mounted) setState(() {});
      return;
    }

    totalRaceTime += dt;
    final int prevLap = currentLap;

    // ERS Logic
    final bool ersActive = ersHeld && ersCharge > 1.5 && speedKmh > 80.0;
    if (ersActive) {
      ersCharge = max(0.0, ersCharge - 26.0 * dt);
    } else {
      ersCharge = min(100.0, ersCharge + (brakeHeld ? 18.0 : 7.5) * dt);
    }

    // Acceleration / Braking / Coasting
    final double maxSpeed = ersActive ? 348.0 : 316.0;
    if (gasHeld) {
      final double accel = ersActive ? 162.0 : 122.0;
      speedKmh = min(maxSpeed, speedKmh + accel * dt);
    } else if (brakeHeld) {
      speedKmh = max(0.0, speedKmh - 265.0 * dt);
    } else {
      speedKmh = max(0.0, speedKmh - 38.0 * dt);
    }

    // Steering & Centrifugal force
    double targetSteer = 0.0;
    if (leftHeld) targetSteer -= 1.0;
    if (rightHeld) targetSteer += 1.0;
    steerAngle += (targetSteer - steerAngle) * min(1.0, dt * 11.0);

    final double curveNow = _trackCurveAt(playerDist);
    final double centrifugal = curveNow * (speedKmh / 320.0) * 0.42;
    carX += (steerAngle * (1.35 + speedKmh / 290.0) - centrifugal) * dt;

    // Kerb / Runoff slowdown if outside track limits
    if (carX.abs() > 0.98) {
      speedKmh = max(65.0, speedKmh - 140.0 * dt);
      carX = carX.clamp(-1.18, 1.18).toDouble();
    }

    final double distStep = (speedKmh / 3.6) * dt;
    playerDist += distStep;
    wheelSpin = (wheelSpin + distStep * 1.4) % (pi * 2);

    if (hitFlash > 0) hitFlash = max(0.0, hitFlash - dt * 3.0);

    // Check Lap completion
    final int newLap = (playerDist / widget.circuit.lapLengthMeters).floor() + 1;
    if (newLap > prevLap) {
      final double lapDuration = totalRaceTime - lapStartTime;
      lapStartTime = totalRaceTime;
      if (lapDuration < bestLapTime) bestLapTime = lapDuration;
      if (lapDuration < fastLapTime) fastLapTime = lapDuration;

      if (newLap > totalLaps) {
        raceFinished = true;
        _timer?.cancel();
        _showFinishDialog();
        return;
      }
    }

    // Update 21 AI cars
    for (final ai in aiDrivers) {
      // Rubber-banding subtly keeps pack exciting
      final double deltaToPlayer = playerDist - ai.trackDist;
      double pace = ai.baseSpeedKmh;
      if (deltaToPlayer > 220) pace += 18.0;
      if (deltaToPlayer < -320) pace -= 14.0;

      ai.trackDist += (pace / 3.6) * dt;

      if (rng.nextDouble() < 0.015) {
        ai.targetLaneX = [-0.62, -0.22, 0.22, 0.62][rng.nextInt(4)];
      }
      ai.laneX += (ai.targetLaneX - ai.laneX) * dt * 1.5;

      // Wheel-to-wheel collision check
      final double dz = ai.trackDist - playerDist;
      if (dz > -4.2 && dz < 4.8 && (ai.laneX - carX).abs() < 0.30) {
        speedKmh = max(60.0, speedKmh * 0.68);
        hitFlash = 0.9;
        carX += (carX >= ai.laneX ? 0.14 : -0.14);
        carX = carX.clamp(-1.1, 1.1).toDouble();
      }
    }

    if (mounted) setState(() {});
  }

  String _formatTime(double seconds) {
    if (seconds >= 900) return '--:--.---';
    final int mins = seconds ~/ 60;
    final int secs = seconds.toInt() % 60;
    final int ms = ((seconds - seconds.floor()) * 1000).toInt();
    return '${mins.toString().padLeft(2, '0')}:${secs.toString().padLeft(2, '0')}.${ms.toString().padLeft(3, '0')}';
  }

  int _pointsForPos(int pos) {
    const List<int> table = [25, 18, 15, 12, 10, 8, 6, 4, 2, 1];
    return pos <= 10 ? table[pos - 1] : 0;
  }

