class MinimapPainter extends CustomPainter {
  final double progress;
  final int seed;

  MinimapPainter({required this.progress, required this.seed});

  @override
  void paint(Canvas canvas, Size size) {
    final double cx = size.width * 0.5;
    final double cy = size.height * 0.5;
    final double r = size.width * 0.34;
    final Path path = Path();
    Offset? dotPos;

    const int steps = 48;
    for (int i = 0; i <= steps; i++) {
      final double t = (i / steps) * pi * 2;
      final double wobble = 1.0 + 0.22 * sin(t * 2 + seed) + 0.14 * cos(t * 3 - seed);
      final double px = cx + cos(t) * r * wobble;
      final double py = cy + sin(t) * r * 0.85 * wobble;
      if (i == 0) {
        path.moveTo(px, py);
      } else {
        path.lineTo(px, py);
      }
      if ((i / steps - progress).abs() < (1.0 / steps)) {
        dotPos = Offset(px, py);
      }
    }
    path.close();

    canvas.drawPath(
      path,
      Paint()
        ..color = Colors.white70
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.4,
    );
    if (dotPos != null) {
      canvas.drawCircle(dotPos, 4.0, Paint()..color = const Color(0xFF00E676));
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

class F1Cockpit3DPainter extends CustomPainter {
  final CircuitInfo circuit;
  final TeamLivery livery;
  final bool cockpitCamera;
  final double speedKmh;
  final int gear;
  final int rpm;
  final double ersCharge;
  final bool ersActive;
  final double carX;
  final double steerAngle;
  final double playerDist;
  final double wheelSpin;
  final List<AiDriver> aiDrivers;
  final double hitFlash;
  final int lapNumber;
  final int position;

  F1Cockpit3DPainter({
    required this.circuit,
    required this.livery,
    required this.cockpitCamera,
    required this.speedKmh,
    required this.gear,
    required this.rpm,
    required this.ersCharge,
    required this.ersActive,
    required this.carX,
    required this.steerAngle,
    required this.playerDist,
    required this.wheelSpin,
    required this.aiDrivers,
    required this.hitFlash,
    required this.lapNumber,
    required this.position,
  });

  double _curveAt(double dist) {
    return (sin(dist * circuit.curveFreq) * 0.65 + cos(dist * circuit.curveFreq * 0.43 + circuit.mapSeed) * 0.35) * circuit.curveAmp;
  }

  Offset _project(double x, double y, double z, double w, double horizonY) {
    final double fov = w * 0.56;
    final double scale = fov / max(z, 0.2);
    return Offset(w * 0.5 + x * scale, horizonY - y * scale);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final double horizonY = cockpitCamera ? h * 0.46 : h * 0.43;

    // 1. Sky with smooth atmospheric gradient
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, horizonY),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [circuit.skyTop, circuit.skyBottom],
        ).createShader(Rect.fromLTWH(0, 0, w, horizonY)),
    );

    // Sun / Stadium lights haze
    canvas.drawCircle(
      Offset(w * 0.78, horizonY * 0.48),
      circuit.nightMode ? 20 : 52,
      Paint()..color = circuit.nightMode ? const Color(0x66FFFDE7) : const Color(0x55FFF3C4),
    );

    // Distant Grandstand Silhouette across horizon
    _drawHorizonGrandstand(canvas, w, horizonY);

    // 2. Ground
    canvas.drawRect(
      Rect.fromLTWH(0, horizonY, w, h - horizonY),
      Paint()..color = circuit.groundColor,
    );

    // 3. Perspective 3D Track + Runoff + Kerbs + Grandstands + Props
    const double roadHalfW = 3.1;
    const double runoffHalfW = 4.6;
    const int segCount = 34;
    const double segLen = 2.2;
    final double zOffset = playerDist % segLen;

    for (int i = segCount; i >= 1; i--) {
      final double z1 = i * segLen - zOffset;
      final double z2 = (i + 1) * segLen - zOffset;
      if (z1 <= 0.45) continue;

      final double worldDist1 = playerDist + z1 * 2.2;
      final double worldDist2 = playerDist + z2 * 2.2;
      final int segIndex = (worldDist1 / segLen).floor();

      final double c1 = _curveAt(worldDist1) * (z1 * 0.085);
      final double c2 = _curveAt(worldDist2) * (z2 * 0.085);
      final double camShift = carX * 2.45;
      final double s1 = c1 - camShift;
      final double s2 = c2 - camShift;

      final double camHeight = cockpitCamera ? -1.15 : -1.85;

      // Painted runoff area (like the blue runoff in Yas Marina / Miami / screenshot)
      final Offset r1L = _project(-runoffHalfW + s1, camHeight, z1, w, horizonY);
      final Offset r1R = _project(runoffHalfW + s1, camHeight, z1, w, horizonY);
      final Offset r2L = _project(-runoffHalfW + s2, camHeight, z2, w, horizonY);
      final Offset r2R = _project(runoffHalfW + s2, camHeight, z2, w, horizonY);

      final double fade = (1.0 - (i / segCount) * 0.52).clamp(0.4, 1.0).toDouble();
      final Path runoffPath = Path()
        ..moveTo(r1L.dx, r1L.dy)
        ..lineTo(r1R.dx, r1R.dy)
        ..lineTo(r2R.dx, r2R.dy)
        ..lineTo(r2L.dx, r2L.dy)
        ..close();
      canvas.drawPath(runoffPath, Paint()..color = circuit.runoffColor);

      // Asphalt surface
      final Offset p1L = _project(-roadHalfW + s1, camHeight, z1, w, horizonY);
      final Offset p1R = _project(roadHalfW + s1, camHeight, z1, w, horizonY);
      final Offset p2L = _project(-roadHalfW + s2, camHeight, z2, w, horizonY);
      final Offset p2R = _project(roadHalfW + s2, camHeight, z2, w, horizonY);

      final bool isStartLine = (worldDist1 % circuit.lapLengthMeters) < 12.0;
      final int shade = ((segIndex % 2 == 0 ? 58 : 50) * fade).toInt();

      final Path roadPath = Path()
        ..moveTo(p1L.dx, p1L.dy)
        ..lineTo(p1R.dx, p1R.dy)
        ..lineTo(p2R.dx, p2R.dy)
        ..lineTo(p2L.dx, p2L.dy)
        ..close();
      canvas.drawPath(
        roadPath,
        Paint()..color = isStartLine ? const Color(0xFFE0E0E0) : Color.fromARGB(255, shade, shade + 1, shade + 4),
      );

      // Subtle darker racing groove in center
      final Offset g1L = _project(-1.5 + s1, camHeight, z1, w, horizonY);
      final Offset g1R = _project(1.5 + s1, camHeight, z1, w, horizonY);
      final Offset g2L = _project(-1.5 + s2, camHeight, z2, w, horizonY);
      final Offset g2R = _project(1.5 + s2, camHeight, z2, w, horizonY);
      final Path groovePath = Path()
        ..moveTo(g1L.dx, g1L.dy)
        ..lineTo(g1R.dx, g1R.dy)
        ..lineTo(g2R.dx, g2R.dy)
        ..lineTo(g2L.dx, g2L.dy)
        ..close();
      canvas.drawPath(groovePath, Paint()..color = const Color(0x20000000));

      // White track-limit lines
      final Paint whiteLine = Paint()
        ..color = Color.fromARGB((210 * fade).toInt(), 245, 245, 245)
        ..strokeWidth = max(1.0, 5.0 / z1);
      canvas.drawLine(p1L, p2L, whiteLine);
      canvas.drawLine(p1R, p2R, whiteLine);

      // Kerbs (red/white or circuit-specific)
      final Paint kerbPaint = Paint()
        ..color = segIndex % 2 == 0 ? circuit.kerbA : circuit.kerbB
        ..strokeWidth = max(2.0, 14.0 / z1);
      canvas.drawLine(
        _project(-roadHalfW - 0.25 + s1, camHeight, z1, w, horizonY),
        _project(-roadHalfW - 0.25 + s2, camHeight, z2, w, horizonY),
        kerbPaint,
      );
      canvas.drawLine(
        _project(roadHalfW + 0.25 + s1, camHeight, z1, w, horizonY),
        _project(roadHalfW + 0.25 + s2, camHeight, z2, w, horizonY),
        kerbPaint,
      );

      // Trackside barriers & grandstands / palms / lights
      if (segIndex % 4 == 0) {
        _drawTracksideProp(canvas, -runoffHalfW - 1.5 + s1, camHeight, z1, w, horizonY, true);
        _drawTracksideProp(canvas, runoffHalfW + 1.5 + s1, camHeight, z1, w, horizonY, false);
      }

      // Start/Finish Overhead Gantry
      if (isStartLine && i > 2) {
        final Offset topL = _project(-roadHalfW - 0.6 + s1, camHeight + 3.2, z1, w, horizonY);
        final Offset topR = _project(roadHalfW + 0.6 + s1, camHeight + 3.2, z1, w, horizonY);
        final Paint gantryPaint = Paint()
          ..color = const Color(0xFF1A1E28)
          ..strokeWidth = max(3.0, 22.0 / z1);
        canvas.drawLine(p1L, topL, gantryPaint);
        canvas.drawLine(p1R, topR, gantryPaint);
        canvas.drawLine(topL, topR, gantryPaint);
      }
    }

    // 4. Rival F1 Cars (sorted far -> near) with 3-letter name tags like the screenshot
    final List<AiDriver> visibleRivals = aiDrivers.where((ai) {
      final double dz = (ai.trackDist - playerDist) / 2.2;
      return dz > 1.2 && dz < 68.0;
    }).toList()
      ..sort((a, b) => b.trackDist.compareTo(a.trackDist));

    for (final ai in visibleRivals) {
      final double z = (ai.trackDist - playerDist) / 2.2;
      final double curveR = _curveAt(ai.trackDist) * (z * 0.085);
      final double rx = (ai.laneX * 2.45) + curveR - (carX * 2.45);
      final double camHeight = cockpitCamera ? -1.15 : -1.85;
      final Offset pos = _project(rx, camHeight, z, w, horizonY);
      final double sc = (w * 0.56) / max(z, 0.5);
      _drawRivalF1Car(canvas, pos, sc, ai);
    }

    // 5. Camera Foreground: Detailed F1 Cockpit (matching screenshot) OR Chase Car
    if (cockpitCamera) {
      _drawCockpitOverlay(canvas, w, h);
    } else {
      _drawChaseCar(canvas, w, h);
    }

    // 6. Speed motion blur streaks
    if (speedKmh > 250) {
      final Paint streakPaint = Paint()
        ..color = Color.fromARGB(((speedKmh - 250) * 0.7).clamp(10, 70).toInt(), 255, 255, 255)
        ..strokeWidth = 1.6;
      for (int k = 0; k < 8; k++) {
        final double lx = (k.isEven ? 0.06 : 0.94) * w;
        final double ly = ((playerDist * 22 + k * 70) % h);
        canvas.drawLine(Offset(lx, ly), Offset(lx, ly + 36), streakPaint);
      }
    }

    // 7. Collision impact flash
    if (hitFlash > 0) {
      canvas.drawRect(
        Rect.fromLTWH(0, 0, w, h),
        Paint()..color = Color.fromARGB((hitFlash * 100).toInt(), 255, 25, 25),
      );
    }
  }

  void _drawHorizonGrandstand(Canvas canvas, double w, double horizonY) {
    // Main grandstands silhouette & multi-tier seating like the screenshot
    final double standTop = horizonY - 42;
    canvas.drawRect(
      Rect.fromLTWH(0, standTop, w * 0.65, 42),
      Paint()..color = circuit.nightMode ? const Color(0xFF151B2B) : const Color(0xFF424A57),
    );
    // Roof overhang
    canvas.drawRect(
      Rect.fromLTWH(0, standTop - 8, w * 0.68, 9),
      Paint()..color = circuit.nightMode ? const Color(0xFF232C42) : const Color(0xFF6B7482),
    );
    // Support pillars
    final Paint pillarPaint = Paint()
      ..color = const Color(0xFF2A303B)
      ..strokeWidth = 3;
    for (int i = 1; i <= 7; i++) {
      final double px = (w * 0.09) * i;
      canvas.drawLine(Offset(px, standTop), Offset(px, horizonY), pillarPaint);
    }
  }

  void _drawTracksideProp(
    Canvas canvas,
    double x,
    double camHeight,
    double z,
    double w,
    double horizonY,
    bool isLeft,
  ) {
    final Offset base = _project(x, camHeight, z, w, horizonY);
    final Offset top = _project(x, camHeight + 3.4, z, w, horizonY);
    final double ph = max(8.0, base.dy - top.dy);
    final double pw = max(6.0, ph * 0.55);

    if (circuit.propStyle == PropStyle.palms) {
      // Palm tree trunk & fronds (like top-right of screenshot!)
      canvas.drawLine(
        base,
        top,
        Paint()
          ..color = const Color(0xFF5D4037)
          ..strokeWidth = max(2.0, pw * 0.16),
      );
      final Paint frondPaint = Paint()
        ..color = circuit.nightMode ? const Color(0xFF1B4D2E) : const Color(0xFF2E6B34)
        ..strokeWidth = max(1.8, pw * 0.14);
      for (int a = 0; a < 5; a++) {
        final double ang = -pi + (a * pi / 4);
        canvas.drawLine(top, Offset(top.dx + cos(ang) * pw * 0.8, top.dy + sin(ang) * pw * 0.45 + 3), frondPaint);
      }
    } else if (circuit.propStyle == PropStyle.skyline) {
      canvas.drawRect(
        Rect.fromLTWH(top.dx - pw * 0.6, top.dy - ph * 0.3, pw * 1.2, ph * 1.3),
        Paint()..color = circuit.nightMode ? const Color(0xFF1C2338) : const Color(0xFF3E485C),
      );
      if (pw > 14) {
        canvas.drawRect(
          Rect.fromLTWH(top.dx - pw * 0.3, top.dy, pw * 0.6, ph * 0.15),
          Paint()..color = circuit.nightMode ? const Color(0xCC00E5FF) : const Color(0x66FFE082),
        );
      }
    } else if (circuit.propStyle == PropStyle.trees) {
      canvas.drawLine(base, Offset(top.dx, base.dy - ph * 0.4), Paint()..color = const Color(0xFF4E342E)..strokeWidth = max(2.0, pw * 0.18));
      canvas.drawCircle(
        Offset(top.dx, base.dy - ph * 0.65),
        pw * 0.55,
        Paint()..color = const Color(0xFF255928),
      );
    } else {
      // Desert light pole / barrier
      canvas.drawLine(base, top, Paint()..color = const Color(0xFF90A4AE)..strokeWidth = max(1.5, pw * 0.12));
      if (circuit.nightMode) {
        canvas.drawCircle(top, max(2.5, pw * 0.2), Paint()..color = const Color(0xDDFFFDE7));
      }
    }
  }

  void _drawRivalF1Car(Canvas canvas, Offset pos, double sc, AiDriver ai) {
    final double cw = (sc * 1.35).clamp(10.0, 220.0).toDouble();
    final double ch = (sc * 0.58).clamp(5.0, 95.0).toDouble();

    // Ground shadow
    canvas.drawOval(
      Rect.fromCenter(center: Offset(pos.dx, pos.dy + ch * 0.08), width: cw * 1.45, height: ch * 0.35),
      Paint()..color = const Color(0xAA000000),
    );
    // Rear wide slick tires
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx - cw * 0.68, pos.dy - ch * 0.92, cw * 0.26, ch * 0.92), Radius.circular(cw * 0.04)),
      Paint()..color = const Color(0xFF141414),
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx + cw * 0.42, pos.dy - ch * 0.92, cw * 0.26, ch * 0.92), Radius.circular(cw * 0.04)),
      Paint()..color = const Color(0xFF141414),
    );
    // Diffuser
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.36, pos.dy - ch * 0.35, cw * 0.72, ch * 0.32), Paint()..color = const Color(0xFF1C1C1C));
    // Engine cover / sidepods
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx - cw * 0.42, pos.dy - ch * 1.05, cw * 0.84, ch * 0.78), Radius.circular(cw * 0.06)),
      Paint()..color = ai.bodyColor,
    );
    // Airbox / T-Cam
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.1, pos.dy - ch * 1.42, cw * 0.2, ch * 0.42), Paint()..color = ai.bodyColor);
    // Rear wing
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.46, pos.dy - ch * 1.24, cw * 0.92, ch * 0.22), Paint()..color = ai.wingColor);
    // Blinking ERS rear light
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.04, pos.dy - ch * 0.48, cw * 0.08, ch * 0.2), Paint()..color = const Color(0xFFFF1744));

    // Floating 3-letter Driver Tag (like "RIC", "TSU" in screenshot!)
    if (cw > 22) {
      final TextPainter tp = TextPainter(
        text: TextSpan(
          text: ai.code,
          style: TextStyle(
            color: Colors.white,
            fontSize: (cw * 0.14).clamp(9.0, 14.0).toDouble(),
            fontWeight: FontWeight.w900,
            shadows: const [Shadow(color: Colors.black, blurRadius: 4)],
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(pos.dx - tp.width * 0.5, pos.dy - ch * 1.55 - tp.height));
    }
  }

  void _drawCockpitOverlay(Canvas canvas, double w, double h) {
    final double cx = w * 0.5;
    final double vib = sin(playerDist * 0.9) * (speedKmh / 320.0) * 1.8;

    // 1. Front Left & Right Slick Tires (visible outside cockpit like screenshot)
    final double wheelShift = steerAngle * 14.0;
    _drawFrontTire(canvas, Offset(w * 0.19 + wheelShift, h * 0.74 + vib), w * 0.14, h * 0.28, true);
    _drawFrontTire(canvas, Offset(w * 0.81 + wheelShift, h * 0.74 + vib), w * 0.14, h * 0.28, false);

    // 2. Front Suspension Carbon Arms
    final Paint suspPaint = Paint()
      ..color = const Color(0xFF1A1D24)
      ..strokeWidth = 7;
    canvas.drawLine(Offset(w * 0.23, h * 0.74 + vib), Offset(w * 0.40, h * 0.78 + vib), suspPaint);
    canvas.drawLine(Offset(w * 0.77, h * 0.74 + vib), Offset(w * 0.60, h * 0.78 + vib), suspPaint);

    // 3. Car Chassis / Side Cockpit Cowling (livery colored with glossy highlight)
    final Path cowling = Path()
      ..moveTo(0, h * 0.72 + vib)
      ..quadraticBezierTo(w * 0.22, h * 0.66 + vib, w * 0.36, h * 0.76 + vib)
      ..lineTo(w * 0.64, h * 0.76 + vib)
      ..quadraticBezierTo(w * 0.78, h * 0.66 + vib, w, h * 0.72 + vib)
      ..lineTo(w, h)
      ..lineTo(0, h)
      ..close();
    canvas.drawPath(
      cowling,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [livery.primary, const Color(0xFF1A070A)],
        ).createShader(Rect.fromLTWH(0, h * 0.65, w, h * 0.35)),
    );

    // Glossy edge highlight along cockpit rim
    canvas.drawPath(
      Path()
        ..moveTo(0, h * 0.72 + vib)
        ..quadraticBezierTo(w * 0.22, h * 0.66 + vib, w * 0.36, h * 0.76 + vib)
        ..lineTo(w * 0.64, h * 0.76 + vib)
        ..quadraticBezierTo(w * 0.78, h * 0.66 + vib, w, h * 0.72 + vib),
      Paint()
        ..color = const Color(0x66FFFFFF)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.5,
    );

    // Interior cockpit shadow well
    canvas.drawRect(
      Rect.fromLTWH(w * 0.24, h * 0.76 + vib, w * 0.52, h * 0.24),
      Paint()..color = const Color(0xFF0D0F14),
    );

    // 4. Carbon-Fiber Halo (Top arch + Central Pillar like screenshot!)
    final Paint haloPaint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [const Color(0xFF1A080C), livery.primary, const Color(0xFF16181F)],
      ).createShader(Rect.fromLTWH(0, 0, w, h * 0.78));

    // Top Halo Arch
    final Path haloArch = Path()
      ..moveTo(0, 0)
      ..lineTo(w, 0)
      ..lineTo(w, h * 0.16)
      ..quadraticBezierTo(cx, h * 0.02, 0, h * 0.16)
      ..close();
    canvas.drawPath(haloArch, haloPaint);

    // Central Halo Pillar
    final Path pillar = Path()
      ..moveTo(cx - 24, h * 0.06)
      ..lineTo(cx + 24, h * 0.06)
      ..lineTo(cx + 12, h * 0.74 + vib)
      ..lineTo(cx - 12, h * 0.74 + vib)
      ..close();
    canvas.drawPath(pillar, haloPaint);

    // 5. Rotating F1 Steering Wheel + Driver Gloved Hands + Telemetry Screen
    canvas.save();
    canvas.translate(cx, h * 0.85 + vib);
    canvas.rotate(steerAngle * 0.42);

    final double swW = (w * 0.36).clamp(210.0, 320.0).toDouble();
    final double swH = (h * 0.30).clamp(115.0, 175.0).toDouble();

    // Carbon wheel body
    final RRect wheelRect = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset.zero, width: swW, height: swH),
      const Radius.circular(18),
    );
    canvas.drawRRect(wheelRect, Paint()..color = const Color(0xFF181B22));
    canvas.drawRRect(
      wheelRect,
      Paint()
        ..color = const Color(0xFF3A4252)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.5,
    );

    // Top RPM Shift LEDs (Green -> Red -> Purple)
    final double rpmRatio = ((rpm - 6000) / 8000.0).clamp(0.0, 1.0).toDouble();
    const int ledCount = 12;
    for (int i = 0; i < ledCount; i++) {
      final bool lit = (i / ledCount) < rpmRatio;
      final Color ledColor = i < 4
          ? const Color(0xFF00E676)
          : (i < 8 ? const Color(0xFFFF1744) : const Color(0xFF2979FF));
      final double lx = -swW * 0.28 + (i * (swW * 0.56 / (ledCount - 1)));
      canvas.drawCircle(
        Offset(lx, -swH * 0.38),
        3.2,
        Paint()..color = lit ? ledColor : const Color(0xFF2A2F3A),
      );
    }

    // Center Digital LCD Telemetry Display (matching screenshot!)
    final Rect lcdRect = Rect.fromCenter(center: Offset(0, -swH * 0.04), width: swW * 0.44, height: swH * 0.52);
    canvas.drawRRect(
      RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)),
      Paint()..color = const Color(0xFF06080D),
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)),
      Paint()
        ..color = ersActive ? const Color(0xFF00E5FF) : const Color(0xFF263238)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.5,
    );

    // LCD Text: Giant Gear + Speed + RPM
    _drawCenteredText(
      canvas,
      '$gear',
      Offset(0, -swH * 0.03),
      swH * 0.25,
      Colors.white,
      FontWeight.w900,
    );
    _drawCenteredText(
      canvas,
      '${speedKmh.toInt()}',
      Offset(-swW * 0.14, -swH * 0.16),
      swH * 0.11,
      const Color(0xFF00E676),
      FontWeight.bold,
    );
    _drawCenteredText(
      canvas,
      '$rpm',
      Offset(0, swH * 0.13),
      swH * 0.085,
      const Color(0xFFB0BEC5),
      FontWeight.bold,
    );

    // Colorful F1 Rotary Knobs along bottom of wheel
    const List<Color> knobColors = [Color(0xFFE53935), Color(0xFF43A047), Color(0xFFFFB300)];
    for (int k = 0; k < 3; k++) {
      final double kx = (k - 1) * (swW * 0.12);
      canvas.drawCircle(Offset(kx, swH * 0.33), swH * 0.08, Paint()..color = knobColors[k]);
      canvas.drawCircle(Offset(kx, swH * 0.33), swH * 0.04, Paint()..color = const Color(0xFF15181F));
    }

    // Left & Right Steering Wheel Buttons
    canvas.drawCircle(Offset(-swW * 0.34, -swH * 0.18), 5, Paint()..color = const Color(0xFF29B6F6));
    canvas.drawCircle(Offset(swW * 0.34, -swH * 0.18), 5, Paint()..color = const Color(0xFFFFCA28));
    canvas.drawCircle(Offset(-swW * 0.32, 0), 4.5, Paint()..color = const Color(0xFFEF5350));
    canvas.drawCircle(Offset(swW * 0.32, 0), 4.5, Paint()..color = const Color(0xFF66BB6A));

    // Driver Gloved Hands gripping the wheel (like red gloves in screenshot!)
    final Paint glovePaint = Paint()..color = livery.gloveColor;
    final Paint gloveShadow = Paint()..color = const Color(0x44000000);
    // Left hand + wrist
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(-swW * 0.56, -swH * 0.15, swW * 0.22, swH * 0.58), const Radius.circular(18)),
      glovePaint,
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(-swW * 0.42, -swH * 0.12, swW * 0.09, swH * 0.18), const Radius.circular(8)),
      gloveShadow,
    );
    // Right hand + wrist
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(swW * 0.34, -swH * 0.15, swW * 0.22, swH * 0.58), const Radius.circular(18)),
      glovePaint,
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(swW * 0.33, -swH * 0.12, swW * 0.09, swH * 0.18), const Radius.circular(8)),
      gloveShadow,
    );

    canvas.restore();
  }

  void _drawFrontTire(Canvas canvas, Offset center, double tw, double th, bool isLeft) {
    final RRect tireRect = RRect.fromRectAndRadius(
      Rect.fromCenter(center: center, width: tw, height: th),
      const Radius.circular(18),
    );
    canvas.drawRRect(
      tireRect,
      Paint()
        ..shader = const LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: [Color(0xFF101216), Color(0xFF2A2F38), Color(0xFF121419)],
        ).createShader(tireRect.outerRect),
    );
    // Red Soft Pirelli Sidewall Stripe
    canvas.drawArc(
      Rect.fromCenter(center: Offset(center.dx + (isLeft ? tw * 0.2 : -tw * 0.2), center.dy), width: tw * 0.45, height: th * 0.65),
      -pi * 0.35,
      pi * 0.7,
      false,
      Paint()
        ..color = const Color(0xFFE10600)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3.2,
    );
  }

  void _drawChaseCar(Canvas canvas, double w, double h) {
    canvas.save();
    canvas.translate(w * 0.5, h * 0.80);
    canvas.rotate(steerAngle * 0.06);

    canvas.drawOval(Rect.fromCenter(center: const Offset(0, 14), width: 170, height: 24), Paint()..color = const Color(0xAA000000));
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-78, -24, 28, 44), const Radius.circular(6)), Paint()..color = const Color(0xFF141414));
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(50, -24, 28, 44), const Radius.circular(6)), Paint()..color = const Color(0xFF141414));
    canvas.drawRect(const Rect.fromLTWH(-46, 2, 92, 14), Paint()..color = const Color(0xFF212121));

    final Path body = Path()
      ..moveTo(-54, 4)
      ..lineTo(-34, -38)
      ..lineTo(34, -38)
      ..lineTo(54, 4)
      ..close();
    canvas.drawPath(body, Paint()..color = livery.primary);

    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-12, -52, 24, 24), const Radius.circular(10)), Paint()..color = const Color(0xFF1A1A1A));
    canvas.drawRect(const Rect.fromLTWH(-4, -2, 8, 10), Paint()..color = const Color(0xFFFF1744));
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(-58, ersActive ? -48 : -40, 116, ersActive ? 7 : 12), const Radius.circular(3)),
      Paint()..color = ersActive ? const Color(0xFF00E5FF) : livery.secondary,
    );
    canvas.restore();
  }

  void _drawCenteredText(Canvas canvas, String text, Offset center, double fontSize, Color color, FontWeight weight) {
    final TextPainter tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(color: color, fontSize: fontSize, fontWeight: weight),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(center.dx - tp.width * 0.5, center.dy - tp.height * 0.5));
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}
